--
-- Name: extract_job_moy(); Type: FUNCTION; Schema: lisa; Owner: -
--

CREATE FUNCTION lisa.extract_job_moy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      BEGIN
      NEW.month_of_year := EXTRACT(month FROM NEW.startedtime);
      RETURN NEW;
      END;
      $$;


