--
-- Name: get_data_directory_disk_usage(); Type: FUNCTION; Schema: lisa; Owner: -
--

CREATE FUNCTION lisa.get_data_directory_disk_usage() RETURNS TABLE(size text, used text, available text, used_pct text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
            DECLARE
                v_data_dir text := current_setting('data_directory');
            BEGIN
                CREATE TEMP TABLE disk_info(line text) ON COMMIT DROP;

                EXECUTE format(
                    'COPY disk_info FROM PROGRAM %L',
                    'df -hP ' || v_data_dir
                        );

                RETURN QUERY
                    SELECT
                        cols[2],
                        cols[3],
                        cols[4],
                        cols[5]
                    FROM (
                             SELECT regexp_split_to_array(trim(line), '\s+') AS cols
                             FROM disk_info
                             OFFSET 1
                         ) s;
            END;
            $$;


--
-- Name: get_fragmentation_stat(); Type: FUNCTION; Schema: lisa; Owner: -
--

CREATE FUNCTION lisa.get_fragmentation_stat() RETURNS TABLE(tablename name, total_table_size_with_all_pages text, used_space_with_actual_data text, dead_space text, free_space text, free_percent double precision, live_tuple_count bigint, dead_tuple_count bigint, last_vacuum_on timestamp with time zone, last_autovacuum_on timestamp with time zone, autovacuum_count bigint)
    LANGUAGE plpgsql
    AS $$
            DECLARE
                r RECORD;
                stats RECORD;
            BEGIN
                FOR r IN
                    SELECT
                        tab.relname AS tablename,
                        psat.n_live_tup AS live_tuple_count,
                        psat.n_dead_tup AS dead_tuple_count,
                        psat.last_vacuum AS last_vacuum_on,
                        psat.last_autovacuum AS last_autovacuum_on,
                        psat.autovacuum_count AS autovacuum_count
                    FROM pg_class tab
                             INNER JOIN pg_namespace ns ON ns.oid = tab.relnamespace
                             INNER JOIN pg_stat_all_tables psat ON tab.relname = psat.relname
                    WHERE tab.relkind = 'r' AND ns.nspname = 'lisa' AND psat.schemaname = 'lisa'
                    ORDER BY pg_total_relation_size(tab.oid) DESC LIMIT 10
                    LOOP
                        EXECUTE format('select * from lisa.pgstattuple(''lisa.%I'')',r.tablename) INTO stats;
                        RETURN QUERY
                            SELECT r.tablename ,
                                   pg_size_pretty(stats.table_len) AS total_table_size_with_all_pages,
                                   pg_size_pretty(stats.tuple_len) AS used_space_with_actual_data,
                                   pg_size_pretty(stats.dead_tuple_len) as dead_space,
                                   pg_size_pretty(stats.free_space) AS free_space,
                                   stats.free_percent,
                                   r.live_tuple_count,
                                   r.dead_tuple_count,
                                   r.last_vacuum_on,
                                   r.last_autovacuum_on,
                                   r.autovacuum_count;
                    END LOOP;
            END;
            $$;


--
-- Name: grant_repack_privileges(); Type: FUNCTION; Schema: lisa; Owner: -
--

CREATE FUNCTION lisa.grant_repack_privileges() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
            BEGIN
                -- Grant usage and create on repack schema
                GRANT USAGE, CREATE
                    ON SCHEMA repack
                    TO lisa;

                -- Grant execute on all functions in repack schema
                GRANT EXECUTE ON ALL FUNCTIONS
                    IN SCHEMA repack
                    TO lisa;

                -- Grant DML on all tables in repack schema
                GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES
                    IN SCHEMA repack
                    TO lisa;

                RETURN 'repack privileges granted successfully';
            END;
            $$;


--
-- Name: pg_repack_reinstall(); Type: FUNCTION; Schema: lisa; Owner: -
--

CREATE FUNCTION lisa.pg_repack_reinstall() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
            DECLARE
                v_session record;
                v_remaining integer;
            BEGIN
                -- Stop active pg_repack sessions first, otherwise DROP EXTENSION can block for a long time.
                FOR v_session IN
                    SELECT pid
                    FROM pg_stat_activity
                    WHERE pid <> pg_backend_pid()
                      AND state IN ('active', 'idle in transaction', 'idle in transaction (aborted)')
                      AND (
                        application_name ILIKE '%repack%'
                      )
                LOOP
                    PERFORM pg_terminate_backend(v_session.pid);
                END LOOP;

                -- Safety check: do not proceed if pg_repack sessions are still active.
                SELECT COUNT(*)
                INTO v_remaining
                FROM pg_stat_activity
                WHERE pid <> pg_backend_pid()
                  AND state IN ('active', 'idle in transaction', 'idle in transaction (aborted)')
                  AND (
                    application_name ILIKE '%repack%'
                  );

                IF v_remaining > 0 THEN
                    RAISE EXCEPTION 'Cannot reinstall pg_repack: % active pg_repack session(s) still running.', v_remaining;
                END IF;

                -- Remove pg_repack and all extension-owned objects
                DROP EXTENSION IF EXISTS pg_repack CASCADE;

                -- Recreate pg_repack
                CREATE EXTENSION IF NOT EXISTS pg_repack;

                -- Restore required privileges assigned during initial setup of pg_repack extension to run via non-superuser role
                GRANT USAGE, CREATE
                    ON SCHEMA repack
                    TO lisa;

                GRANT EXECUTE ON ALL FUNCTIONS
                    IN SCHEMA repack
                    TO lisa;

                GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES
                    IN SCHEMA repack
                    TO lisa;
                RETURN 'pg_repack successfully reinstalled';
            END;
            $$;


