-- Name: data_synchronizer_task; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.data_synchronizer_task (
    id numeric(18,0) NOT NULL,
    sync_start_date timestamp with time zone NOT NULL,
    sync_end_date timestamp with time zone NOT NULL,
    sync_progress timestamp with time zone,
    execution_start_date timestamp with time zone,
    execution_end_date timestamp with time zone,
    sync_jobs numeric(1,0),
    sync_iact numeric(1,0),
    sync_documents numeric(1,0),
    sync_document_types character varying(4000),
    target_lis character varying(255),
    message_count numeric(9,0),
    status character varying(255) NOT NULL,
    exposure_machine_ids character varying(4000),
    metrology_machine_ids character varying(4000),
    iact_sync_compute_jobs numeric(1,0),
    iact_sync_process_jobs numeric(1,0),
    job_types character varying(4000),
    iact_sync_otas_jobs numeric(1,0),
    target_plugin character varying(255),
    task_type character varying(255),
    delete_inventory_data numeric(1,0),
    iact_sync_process_job_doc numeric(1,0)
);


--
-- Name: COLUMN data_synchronizer_task.id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.id IS 'Id';


--
-- Name: COLUMN data_synchronizer_task.sync_jobs; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.sync_jobs IS '1 = Enable job synchronization between JOQM and LANA';


--
-- Name: COLUMN data_synchronizer_task.sync_iact; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.sync_iact IS '1 = Enable synchronization between LANA and Inventory/iACT';


--
-- Name: COLUMN data_synchronizer_task.sync_documents; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.sync_documents IS '1 = Enable document synchronization between OBST and LANA';


--
-- Name: COLUMN data_synchronizer_task.sync_document_types; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.sync_document_types IS 'Comma separated list of ADEL document types to be synchronized between OBST and LANA. Empty for default list.';


--
-- Name: COLUMN data_synchronizer_task.target_lis; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.target_lis IS 'Target LIS for document and job synchronization.';


--
-- Name: COLUMN data_synchronizer_task.message_count; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.message_count IS 'Number of created messages during this synchronization run.';


--
-- Name: COLUMN data_synchronizer_task.status; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.status IS 'Planned, Running, Finished, Cancelled';


--
-- Name: COLUMN data_synchronizer_task.exposure_machine_ids; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.exposure_machine_ids IS 'Comma separated list of exposure machine ids used for filtering during DS runs. Empty list means no filtering.';


--
-- Name: COLUMN data_synchronizer_task.metrology_machine_ids; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.metrology_machine_ids IS 'Comma separated list of metrology machine ids used for filtering during DS runs. Empty list means no filtering.';


--
-- Name: COLUMN data_synchronizer_task.iact_sync_compute_jobs; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.iact_sync_compute_jobs IS 'Enable synchronization of compute jobs between LANA and iACT.';


--
-- Name: COLUMN data_synchronizer_task.iact_sync_process_jobs; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.iact_sync_process_jobs IS 'Enable synchronization of process jobs between LANA and iACT.';


--
-- Name: COLUMN data_synchronizer_task.job_types; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.job_types IS 'Comma separated list of job types (e.g. ''alignment/monitor'') used for filtering during DS runs. Empty list means no filtering.';


--
-- Name: COLUMN data_synchronizer_task.iact_sync_otas_jobs; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.iact_sync_otas_jobs IS 'Enable synchronization of OTAS jobs between LANA and iACT.';


--
-- Name: COLUMN data_synchronizer_task.target_plugin; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.target_plugin IS 'DC/OS name (as well as the subscription id in HornetQ) of the plugin for which we want to trigger the synchronization.';


--
-- Name: COLUMN data_synchronizer_task.task_type; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.task_type IS 'Task type that describes weather task is doing data synchronization or removes the data.';


--
-- Name: COLUMN data_synchronizer_task.delete_inventory_data; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.data_synchronizer_task.delete_inventory_data IS 'Describes whether plugin removal task removes plugins Inventory data. If false, it marks them as proxy.';


--
