--
-- Name: exposure_process_job; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.exposure_process_job AS
 SELECT id,
    reticle_id AS key_reticle_id,
    rework_counter,
    ((reworked)::integer)::boolean AS reworked,
    (jsonb_build_object('lotId', lot_id, 'equipmentId', machine_id, 'lotStart', replace(to_char((lot_start AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'::text), '.000Z'::text, 'Z'::text), 'processJobType', 'EXPOSURE'))::text AS process_job_id,
    lot_id,
    key_lot_id,
    layer_id,
    key_layer_id AS key_physical_layer_id,
    product_id,
    machine_id AS equipment_id,
    lot_start AS start_time,
    lot_end AS end_time,
    recipe_name,
    software_release,
    ((latest_reworked)::integer)::boolean AS latest_reworked,
        CASE
            WHEN (((reworked)::integer)::boolean IS FALSE) THEN 'NON_REWORKED'::text
            WHEN (((latest_reworked)::integer)::boolean IS TRUE) THEN 'LATEST_REWORKED'::text
            ELSE NULL::text
        END AS rework_context,
    lis_instance_name
   FROM lisa.lot_exposure_step;


