--
-- Name: job; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.job (
    id numeric(18,0) NOT NULL,
    key_job_id character varying(255) NOT NULL,
    type character varying(255),
    startedtime timestamp with time zone,
    finishedtime timestamp with time zone,
    status character varying(255),
    message character varying(4000),
    model_applied character varying(4000),
    ctx_id numeric(18,0),
    ctx_device character varying(255),
    ctx_etchchamber character varying(255),
    ctx_exposureequipment character varying(255),
    ctx_prevexposureequipment character varying(255),
    ctx_layer character varying(255),
    ctx_reticle character varying(255),
    ctx_technology character varying(255),
    ctx_trackpath character varying(255),
    fp_type character varying(255),
    fp_startnewtimefiltersequence character varying(255),
    month_of_year numeric,
    combined_evaluated numeric(1,0),
    createdtime timestamp with time zone,
    application character varying(255),
    bali_control_functions character varying(255),
    cmtd_device_feature character varying(255),
    ctx_requester character varying(255),
    ctx_shadowmode character varying(255),
    machine_id character varying(255),
    ctx_hmq character varying(255),
    ctx_sub_recipe_rule character varying(255),
    sub_recipe_name character varying(255),
    message_codes character varying(1000),
    target_exp_equip_id character varying(255),
    target_exp_cust_equip_id character varying(255),
    estimation_job_type character varying(255),
    software_release character varying(255),
    document_type_version character varying(255),
    document_type character varying(255),
    instance_id character varying(255),
    fp_update_requested character varying(255),
    ctx_p_j_id character varying(255),
    parent_key_job_id character varying(255),
    fp_ctx_custom character varying(4000),
    instance_name character varying(4000),
    control_mode character varying(255),
    control_strategy character varying(255),
    ov_est_recipe_target_label_x character varying(4000),
    ov_est_recipe_target_label_y character varying(4000),
    installed_patches character varying(4000),
    sub_recipe_change_time timestamp with time zone,
    fp_updated numeric(1,0),
    metrology_machine_id_aei character varying(255),
    metrology_recipe_name_aei character varying(255),
    metrology_machine_id_adi character varying(255),
    metrology_recipe_name_adi character varying(255),
    wafer_count numeric(18,0),
    grouping_model_name character varying(255),
    ctx_custom character varying(4000),
    model_modified_time timestamp with time zone,
    estimation_recipe_gl character varying(4000),
    estimation_recipe_rf character varying(4000),
    model_applied_gl character varying(255),
    model_applied_rf character varying(255),
    ovl_est_rec_target_label_x_gl character varying(4000),
    ovl_est_rec_target_label_y_gl character varying(4000),
    ovl_est_rec_target_label_x_rf character varying(4000),
    ovl_est_rec_target_label_y_rf character varying(4000),
    subsampled_met_doc_id character varying(255),
    invalidated numeric(1,0) DEFAULT 0 NOT NULL,
    ibwq_version numeric(38,19),
    job_recipe_name character varying(4000),
    upload_session_key character varying(255),
    vcp_version character varying(4000),
    fp_updated_partial numeric(1,0),
    fp_contribution_to_time_flt numeric(38,19),
    lis_instance_name character varying(255),
    application_name character varying(255),
    recipe_name character varying(255),
    bali_product character varying(255),
    bali_domain character varying(255)
);


