--
-- Name: job_machin_to_machin_mmo_kpis; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.job_machin_to_machin_mmo_kpis (
    job_id numeric(18,0) NOT NULL,
    main_machine_id character varying(255) NOT NULL,
    matched_machine_id character varying(255) NOT NULL,
    main_job_id numeric(18,0) NOT NULL,
    matched_job_id numeric(18,0) NOT NULL,
    main_exposure_lot_start timestamp with time zone,
    class_identifier character varying(4000),
    k_incl_contr_m3s_x numeric(38,19),
    k_incl_contr_max99_7_x numeric(38,19),
    k_incl_contr_m3s_y numeric(38,19),
    k_incl_contr_max99_7_y numeric(38,19),
    k_incl_uncontr_m3s_x numeric(38,19),
    k_incl_uncontr_max99_7_x numeric(38,19),
    k_incl_uncontr_m3s_y numeric(38,19),
    k_incl_uncontr_max99_7_y numeric(38,19),
    k_excl_contr_m3s_x numeric(38,19),
    k_excl_contr_max99_7_x numeric(38,19),
    k_excl_contr_m3s_y numeric(38,19),
    k_excl_contr_max99_7_y numeric(38,19),
    k_excl_uncontr_m3s_x numeric(38,19),
    k_excl_uncontr_max99_7_x numeric(38,19),
    k_excl_uncontr_m3s_y numeric(38,19),
    k_excl_uncontr_max99_7_y numeric(38,19),
    matched_exposure_lot_start timestamp with time zone
);


