--
-- Name: job_ovl_est_recipe_settings; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.job_ovl_est_recipe_settings (
    id numeric(18,0) NOT NULL,
    job_id numeric(18,0) NOT NULL,
    recipe_name character varying(255),
    recipe_type character varying(255),
    health_filter_max numeric(38,19),
    health_filter_nsigma numeric(38,19),
    health_filter_x_max numeric(38,19),
    health_filter_x_nsigma numeric(38,19),
    health_filter_y_max numeric(38,19),
    health_filter_y_nsigma numeric(38,19),
    health_filter_edgeclearance numeric(38,19),
    health_filter_granularity character varying(255),
    residual_outlier_rm_nsigma numeric(38,19),
    kpi_gl_innerfield_threshold numeric(19,0),
    kpi_gl_edgefield_threshold numeric(19,0),
    kpi_x_innerfield_threshold numeric(19,0),
    kpi_x_edgefield_threshold numeric(19,0),
    kpi_y_innerfield_threshold numeric(19,0),
    kpi_y_edgefield_threshold numeric(19,0),
    model_x_max_model_uncertainty numeric(38,19),
    model_y_max_model_uncertainty numeric(38,19),
    use_measured_ovl numeric(1,0),
    model_param_reduct numeric(1,0),
    layout_param_reduct numeric(1,0),
    model_uncertainty_param_reduct numeric(1,0),
    innf_x_max_model_uncertainty numeric(38,19),
    innf_y_max_model_uncertainty numeric(38,19),
    sfldfpup_innf_thr_rtio_validpt numeric(38,19),
    sfldfpup_innf_thr_model_uncert numeric(38,19),
    sfldfpup_innf_thr_ovl_impact numeric(38,19),
    sfldfpup_innf_target_category character varying(255),
    sfldfpup_edge_thr_rtio_validpt numeric(38,19),
    sfldfpup_edge_thr_model_uncert numeric(38,19),
    sfldfpup_edge_target_category character varying(255),
    sep_health_filter_settings numeric(1,0)
);


