--
-- Name: latest_exposure; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.latest_exposure AS
 SELECT lot_exposure_step_id,
    lot_metrology_step_id
   FROM lisa.lot_kpi_mapping
  WHERE (((aggregation_level)::text = 'LOT'::text) AND (lot_exposure_step_id IS NOT NULL) AND (lot_metrology_step_id IS NOT NULL));


