--
-- Name: lis_job; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.lis_job AS
 SELECT id,
    instance_id,
    split_part((type)::text, '/'::text, 1) AS application_id,
    split_part((type)::text, '/'::text, 2) AS request_type,
    type,
    vcp_version,
    key_job_id AS compute_job_id,
    application,
    createdtime AS created_time,
    startedtime AS start_time,
    finishedtime AS end_time,
    status,
    software_release,
    NULL::text AS job_report_id,
    lis_instance_name,
    application_name,
    recipe_name,
    machine_id
   FROM lisa.job
  WHERE (lower((application)::text) = lower('Litho InSight'::text));


