-- Name: lot_exposure_alignment_kpis; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.lot_exposure_alignment_kpis (
    id numeric(18,0) NOT NULL,
    residual_m3s_x numeric(38,19),
    residual_m3s_y numeric(38,19),
    strategy_id character varying(1000),
    strategy_type character varying(1000),
    marks_required_combined character varying(1000),
    marks_required_coarse_x character varying(1000),
    marks_required_coarse_y character varying(1000),
    marks_required_fine_x character varying(1000),
    marks_required_fine_y character varying(1000),
    marks_available_combined character varying(1000),
    marks_available_coarse_x character varying(1000),
    marks_available_coarse_y character varying(1000),
    marks_available_fine_x character varying(1000),
    marks_available_fine_y character varying(1000),
    max_model_residue character varying(1000),
    wafer_grid_correction_model character varying(1000),
    mark_id character varying(4000),
    mark_type character varying(4000),
    variant_id character varying(4000),
    ropi_combined numeric(38,19),
    ropi_x numeric(38,19),
    ropi_y numeric(38,19),
    rpn_x numeric(38,19),
    rpn_y numeric(38,19),
    rpn_combined numeric(38,19),
    ropi_active_x numeric(38,19),
    ropi_active_y numeric(38,19),
    ropi_active_combined numeric(38,19),
    rpn_active_x numeric(38,19),
    rpn_active_y numeric(38,19),
    rpn_active_combined numeric(38,19),
    max_delta_80_to_88_shift character varying(4000),
    minimal_mark_distance character varying(4000),
    st_ropi_active_max_x numeric(38,19),
    st_ropi_active_max_y numeric(38,19),
    st_rpn_active_max_x numeric(38,19),
    st_rpn_active_max_y numeric(38,19),
    st_ropi_active_min_x numeric(38,19),
    st_ropi_active_min_y numeric(38,19),
    st_rpn_active_min_x numeric(38,19),
    st_rpn_active_min_y numeric(38,19),
    st_wq_min_x numeric(38,19),
    st_wq_max_x numeric(38,19),
    st_wq_mean_x numeric(38,19),
    st_mcc_min_x numeric(38,19),
    st_mcc_max_x numeric(38,19),
    st_mcc_mean_x numeric(38,19),
    st_wqvi_min_x numeric(38,19),
    st_wqvi_max_x numeric(38,19),
    st_wqvi_mean_x numeric(38,19),
    st_wq_min_y numeric(38,19),
    st_wq_max_y numeric(38,19),
    st_wq_mean_y numeric(38,19),
    st_mcc_min_y numeric(38,19),
    st_mcc_max_y numeric(38,19),
    st_mcc_mean_y numeric(38,19),
    st_wqvi_min_y numeric(38,19),
    st_wqvi_max_y numeric(38,19),
    st_wqvi_mean_y numeric(38,19),
    rejected_marks_fiwa_x_min numeric(18,0),
    rejected_marks_fiwa_x_max numeric(18,0),
    rejected_marks_fiwa_y_min numeric(18,0),
    rejected_marks_fiwa_y_max numeric(18,0),
    color_deviation_x numeric(38,19),
    color_deviation_y numeric(38,19),
    st_color_deviation_max_x numeric(38,19),
    st_color_deviation_max_y numeric(38,19),
    st_color_deviation_min_x numeric(38,19),
    st_color_deviation_min_y numeric(38,19)
);


