CREATE TABLE lisa.lot_icot_computation (
    id numeric(18,0) NOT NULL,
    startedtime timestamp with time zone,
    finishedtime timestamp with time zone,
    status character varying(255),
    message character varying(4000),
    applied_configuration character varying(4000),
    foup_id numeric(18,0)
);


--
-- Name: COLUMN lot_icot_computation.id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_icot_computation.id IS 'foreign key to LOT_KPI_MAPPING';


--
-- Name: COLUMN lot_icot_computation.startedtime; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_icot_computation.startedtime IS 'Time when icot calculation was started';


--
-- Name: COLUMN lot_icot_computation.finishedtime; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_icot_computation.finishedtime IS 'Time when icot calculation finished';


--
-- Name: COLUMN lot_icot_computation.status; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_icot_computation.status IS 'State of the calculation: PROCESSING, VALIDATION_NOK, PRETREATMENT_NOK, UNEXPECTED_ERROR, FULLY_PROCESSED_OK';


--
-- Name: COLUMN lot_icot_computation.message; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_icot_computation.message IS 'details in case of problems (state!=FULLY_PROCESSED_OK)';


--
-- Name: COLUMN lot_icot_computation.applied_configuration; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_icot_computation.applied_configuration IS 'the COFA parameters that were productive when this calculation was made';


