CREATE TABLE lisa.lot_metrology_step (
    id numeric(18,0) NOT NULL,
    key_lot_id character varying(255) NOT NULL,
    key_layer_id character varying(255) NOT NULL,
    lot_step_id numeric(18,0) NOT NULL,
    machine_id character varying(255) NOT NULL,
    lot_start timestamp with time zone NOT NULL,
    lot_end timestamp with time zone NOT NULL,
    lot_id character varying(255),
    layer_id character varying(255),
    product_id character varying(255),
    process_job_id character varying(255),
    document_name character varying(255),
    document_url character varying(4000),
    document_id character varying(255),
    document_type character varying(255),
    document_version character varying(255),
    recipe_name character varying(255),
