--
-- Name: lot_step; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.lot_step (
    id numeric(18,0) NOT NULL,
    key_lot_id character varying(512) NOT NULL,
    key_layer_id character varying(512) NOT NULL,
    import_timestamp timestamp with time zone NOT NULL,
    lot_start timestamp with time zone NOT NULL,
    month_of_year numeric,
    product_id character varying(255),
    parent_lot_id character varying(255),
    ols_column numeric(10,0)
);


--
-- Name: COLUMN lot_step.id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.id IS 'NA';


--
-- Name: COLUMN lot_step.key_lot_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.key_lot_id IS 'NA';


--
-- Name: COLUMN lot_step.key_layer_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.key_layer_id IS 'NA';


--
-- Name: COLUMN lot_step.import_timestamp; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.import_timestamp IS 'NA';


--
-- Name: COLUMN lot_step.lot_start; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.lot_start IS '/ADELler:Report/Conditions/LotStart';


--
-- Name: COLUMN lot_step.month_of_year; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.month_of_year IS 'NA';


--
-- Name: COLUMN lot_step.product_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.product_id IS '/ADELmetrology:MetrologyReport/Input/RecipeInformation/ProductId';


--
-- Name: COLUMN lot_step.parent_lot_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.parent_lot_id IS 'Will be filled if applicable with the parent LotId';


--
-- Name: COLUMN lot_step.ols_column; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.lot_step.ols_column IS 'Oracle Label Security Column.';


