--
-- Name: measure_process_job; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.measure_process_job AS
 SELECT id,
    wafer_diameter,
    process_job_id AS input_lot_id,
    (jsonb_build_object('lotId', lot_id, 'equipmentId', machine_id, 'lotStart', replace(to_char((lot_start AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'::text), '.000Z'::text, 'Z'::text), 'processJobType', 'MEASURE'))::text AS process_job_id,
    lot_id,
    key_lot_id,
    layer_id,
    key_layer_id AS key_physical_layer_id,
    product_id,
    (wafer_load_orientation)::integer AS wafer_rotation,
    machine_id AS equipment_id,
    lot_start AS start_time,
    lot_end AS end_time,
    recipe_name,
    software_release,
    lis_instance_name
   FROM lisa.lot_metrology_step;


