--
-- Name: vw_customer_name; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.vw_customer_name AS
 SELECT exposure_machine.customername AS customer_name
   FROM lisa.exposure_machine
UNION
 SELECT metrology_machine.customername AS customer_name
   FROM lisa.metrology_machine;


--
-- Name: vw_full_triplet; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.vw_full_triplet AS
 SELECT lec.lot_exposure_step_id,
    lec.lot_metrology_step_id,
    l2e.job_id
   FROM lisa.latest_exposure lec,
    lisa.job_has_input_exposure l2e,
    lisa.job_has_input_measure l2m
  WHERE ((lec.lot_metrology_step_id = l2m.lot_metrology_step_id) AND (l2m.job_id = l2e.job_id) AND (l2e.lot_exposure_step_id = lec.lot_exposure_step_id));


--
-- Name: vw_layer_id; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.vw_layer_id AS
 SELECT DISTINCT key_layer_id
   FROM lisa.lot_step
  ORDER BY key_layer_id;


--
-- Name: vw_product_id; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.vw_product_id AS
 SELECT lot_metrology_step.product_id
   FROM lisa.lot_metrology_step
UNION
 SELECT lot_exposure_step.product_id
   FROM lisa.lot_exposure_step
  ORDER BY 1;


