--
-- Name: wafer_diag_quartile_group_kpis; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.wafer_diag_quartile_group_kpis (
    id numeric(18,0) NOT NULL,
    measurement_profile character varying(2000),
    target_label character varying(2000),
    sampling_scheme character varying(2000),
    aggregation_group character varying(50),
    measurement_type character varying(50),
    dto_ss_iqr_x numeric(38,18),
    dto_ss_iqr_y numeric(38,18),
    dto_ss_lav_x numeric(38,18),
    dto_ss_lav_y numeric(38,18),
    dto_ss_max_x numeric(38,18),
    dto_ss_max_y numeric(38,18),
    dto_ss_median_x numeric(38,18),
    dto_ss_median_y numeric(38,18),
    dto_ss_min_x numeric(38,18),
    dto_ss_min_y numeric(38,18),
    dto_ss_q1_x numeric(38,18),
    dto_ss_q1_y numeric(38,18),
    dto_ss_q3_x numeric(38,18),
    dto_ss_q3_y numeric(38,18),
    dto_ss_uav_x numeric(38,18),
    dto_ss_uav_y numeric(38,18),
    pattern_recogn_score_iqr_x numeric(38,18),
    pattern_recogn_score_iqr_y numeric(38,18),
    pattern_recogn_score_lav_x numeric(38,18),
    pattern_recogn_score_lav_y numeric(38,18),
    pattern_recogn_score_max_x numeric(38,18),
    pattern_recogn_score_max_y numeric(38,18),
    pattern_recogn_score_median_x numeric(38,18),
    pattern_recogn_score_median_y numeric(38,18),
    pattern_recogn_score_min_x numeric(38,18),
    pattern_recogn_score_min_y numeric(38,18),
    pattern_recogn_score_q1_x numeric(38,18),
    pattern_recogn_score_q1_y numeric(38,18),
    pattern_recogn_score_q3_x numeric(38,18),
    pattern_recogn_score_q3_y numeric(38,18),
    pattern_recogn_score_uav_x numeric(38,18),
    pattern_recogn_score_uav_y numeric(38,18)
);


