CREATE TABLE lisa.wafer_ebeam_overlay_step (
    id numeric(18,0) NOT NULL,
    wafer_step_id numeric(18,0) NOT NULL,
    lot_ebeam_overlay_step_id numeric(18,0) NOT NULL,
    key_wafer_id character varying(255),
    wafer_id character varying(255),
    wafer_sequence_nr numeric(18,0),
    status character varying(255),
    key_lot_id character varying(255),
    key_layer_id character varying(255),
    machine_id character varying(255) NOT NULL,
    start_time timestamp with time zone,
    end_time timestamp with time zone,
    lot_id character varying(255),
    layer_id character varying(255),
    product_id character varying(255),
    document_name character varying(255),
