--
-- Name: wafer_exposure_step; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.wafer_exposure_step (
    id numeric(18,0) NOT NULL,
    wafer_step_id numeric(18,0) NOT NULL,
    lot_exposure_step_id numeric(18,0) NOT NULL,
    key_wafer_id character varying(255) NOT NULL,
    wafer_id character varying(255),
    wafer_sequencenr numeric(18,0),
    chuck_id character varying(255),
    processing_time numeric(38,19),
    reject_reason character varying(255),
    wafer_rotation character varying(225),
    focus_spot_mon_enabled numeric(1,0),
    round_edge_clearance numeric(38,19),
    focus_edge_clearance numeric(38,19),
    edge_leveling_algo_type character varying(225),
    edge_leveling_algo_radius numeric(38,19),
    wafer_result character varying(255),
    wafer_exposure_result character varying(255),
    wafer_start timestamp with time zone,
    wafer_end timestamp with time zone,
    image_id character varying(4000),
    rework_counter numeric(4,0),
    reworked numeric(1,0),
    subst_lot_id character varying(255)
);


