--
-- Name: wafer_exposure_process_job; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.wafer_exposure_process_job AS
 SELECT wafer.id,
    wafer.wafer_id,
    wafer.wafer_sequencenr AS wafer_processing_order,
    wafer.wafer_start AS start_time,
    wafer.wafer_end AS end_time,
    wafer.wafer_result AS status,
    wafer.wafer_sequencenr AS wafer_sequence_number,
    wafer.chuck_id,
    wafer.key_wafer_id,
    wafer.rework_counter,
    ((wafer.reworked)::integer)::boolean AS reworked,
    (jsonb_build_object('lotId', lot.lot_id, 'equipmentId', lot.machine_id, 'lotStart', replace(to_char((lot.lot_start AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'::text), '.000Z'::text, 'Z'::text), 'processJobType', 'EXPOSURE'))::text AS process_job_id,
    (jsonb_build_object('processJobId', jsonb_build_object('lotId', lot.lot_id, 'equipmentId', lot.machine_id, 'lotStart', replace(to_char((lot.lot_start AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'::text), '.000Z'::text, 'Z'::text), 'processJobType', 'EXPOSURE'), 'waferId', wafer.wafer_id, 'waferProcessingOrder', wafer.wafer_sequencenr))::text AS wafer_process_job_id,
    lot.id AS lot_exposure_step_id
   FROM (lisa.wafer_exposure_step wafer
     LEFT JOIN lisa.lot_exposure_step lot ON ((wafer.lot_exposure_step_id = lot.id)));


