    filtered_mean numeric(38,19),
    filtered_sigma numeric(38,19),
    residual_min numeric(38,19),
    residual_max numeric(38,19),
    residual_mean numeric(38,19),
    residual_sigma numeric(38,19),
    measured_m3s numeric(38,19),
    measured_nr_dies numeric(38,19),
    measured_nr_dies_spec numeric(38,19),
    measured_dis numeric(38,19),
    measured_nr_full_dies numeric(38,19),
    measured_nr_full_dies_spec numeric(38,19),
    measured_full_dis numeric(38,19),
    measured_nr_partial_dies numeric(38,19),
    measured_nr_partial_dies_spec numeric(38,19),
    measured_partial_dis numeric(38,19),
    filtered_m3s numeric(38,19),
    filtered_nr_dies numeric(38,19),
    filtered_nr_dies_spec numeric(38,19),
    filtered_dis numeric(38,19),
    filtered_nr_full_dies numeric(38,19),
    filtered_nr_full_dies_spec numeric(38,19),
    filtered_full_dis numeric(38,19),
    filtered_nr_partial_dies numeric(38,19),
    filtered_nr_partial_dies_spec numeric(38,19),
    filtered_partial_dis numeric(38,19),
    residual_m3s numeric(38,19),
    residual_nr_dies numeric(38,19),
    residual_nr_dies_spec numeric(38,19),
    residual_dis numeric(38,19),
    residual_nr_full_dies numeric(38,19),
    residual_nr_full_dies_spec numeric(38,19),
    residual_full_dis numeric(38,19),
    residual_nr_partial_dies numeric(38,19),
    residual_nr_partial_dies_spec numeric(38,19),
    residual_partial_dis numeric(38,19),
    model_min numeric(38,19),
    model_max numeric(38,19),
