    qa_dose_x numeric(18,0),
    qa_dose_y numeric(18,0),
    qa_measurement_profile_name_x character varying(255),
    qa_measurement_profile_name_y character varying(255),
    qa_target_sigma_mean_x numeric(38,19),
    qa_target_sigma_mean_y numeric(38,19),
    qa_target_sigma_sigma_x numeric(38,19),
    qa_target_sigma_sigma_y numeric(38,19),
    qa_intensity_mean_x numeric(38,19),
    qa_intensity_mean_y numeric(38,19),
    qa_intensity_sigma_x numeric(38,19),
    qa_intensity_sigma_y numeric(38,19),
    qa_reference_ma_time_x numeric(38,19),
    qa_reference_ma_time_y numeric(38,19),
    qa_accuracy_x numeric(38,19),
    qa_accuracy_y numeric(38,19),
    qp_static_precision_x numeric(38,19),
    qp_static_precision_y numeric(38,19),
    qp_dynamic_precision_x numeric(38,19),
    qp_dynamic_precision_y numeric(38,19),
    qp_tmu_x numeric(38,19),
    qp_tmu_y numeric(38,19),
    tl_target_pitch_x numeric(18,0),
    tl_target_pitch_y numeric(18,0),
    tl_target_bias_x numeric(18,0),
    tl_target_bias_y numeric(18,0),
    mr_edgeremoval_perpendicular_x numeric(38,19),
    mr_edgeremoval_perpendicular_y numeric(38,19),
    mr_edgeremoval_parallel_x numeric(38,19),
    mr_edgeremoval_parallel_y numeric(38,19),
    ranking_number_x numeric(19,0),
    ranking_number_y numeric(19,0),
    qa_sampling_scheme_name_x character varying(255),
    qa_sampling_scheme_name_y character varying(255),
    qa_stack_sensitivity_mean_x numeric(38,19),
    qa_stack_sensitivity_mean_y numeric(38,19),
    qa_stack_sensitivity_sigma_x numeric(38,19),
    qa_stack_sensitivity_sigma_y numeric(38,19),
    qa_dto_x numeric(38,19),
    qa_dto_y numeric(38,19),
    grating_set_name character varying(255),
    qa_measurement_profile_id_x character varying(255),
    qa_measurement_profile_id_y character varying(255),
    pp_dose_x numeric(38,19),
    pp_dose_y numeric(38,19),
    pp_stack_sensitivity_mean_x numeric(38,19),
    pp_stack_sensitivity_mean_y numeric(38,19),
    pp_stack_sensitivity_sigma_x numeric(38,19),
    pp_stack_sensitivity_sigma_y numeric(38,19),
    qa_k_0_mean_x numeric(38,19),
    qa_k_0_mean_y numeric(38,19),
    qa_k_0_sigma_x numeric(38,19),
    qa_k_0_sigma_y numeric(38,19),
    qa_k_0_robustness_x numeric(38,19),
    qa_k_0_robustness_y numeric(38,19),
    qa_k_180_mean_x numeric(38,19),
    qa_k_180_mean_y numeric(38,19),
    qa_k_180_sigma_x numeric(38,19),
    qa_k_180_sigma_y numeric(38,19),
    qa_k_180_robustness_x numeric(38,19),
    qa_k_180_robustness_y numeric(38,19)
);


