--
-- Name: wafer_kpi_mapping; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.wafer_kpi_mapping (
    id numeric(18,0) NOT NULL,
    wafer_step_id numeric(18,0) NOT NULL,
    wafer_metrology_step_id numeric(18,0),
    wafer_exposure_step_id numeric(18,0)
);


--
-- Name: COLUMN wafer_kpi_mapping.id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.wafer_kpi_mapping.id IS 'NA';


--
-- Name: COLUMN wafer_kpi_mapping.wafer_step_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.wafer_kpi_mapping.wafer_step_id IS 'NA';


--
-- Name: COLUMN wafer_kpi_mapping.wafer_metrology_step_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.wafer_kpi_mapping.wafer_metrology_step_id IS 'NA';


--
-- Name: COLUMN wafer_kpi_mapping.wafer_exposure_step_id; Type: COMMENT; Schema: lisa; Owner: -
--

COMMENT ON COLUMN lisa.wafer_kpi_mapping.wafer_exposure_step_id IS 'NA';


--
-- Name: wafer_latest_exposure; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.wafer_latest_exposure AS
 SELECT wafer_exposure_step_id,
    wafer_metrology_step_id
   FROM lisa.wafer_kpi_mapping
  WHERE ((wafer_exposure_step_id IS NOT NULL) AND (wafer_metrology_step_id IS NOT NULL));


