--
-- Name: wafer_measure_process_job; Type: VIEW; Schema: lisa; Owner: -
--

CREATE VIEW lisa.wafer_measure_process_job AS
 SELECT wafer.id,
    wafer.wafer_id,
    wafer.wafer_sequencenr AS wafer_processing_order,
    wafer.measurement_start_time AS start_time,
    wafer.status,
    wafer.key_wafer_id,
    (jsonb_build_object('lotId', lot.lot_id, 'equipmentId', lot.machine_id, 'lotStart', replace(to_char((lot.lot_start AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'::text), '.000Z'::text, 'Z'::text), 'processJobType', 'MEASURE'))::text AS process_job_id,
    (jsonb_build_object('processJobId', jsonb_build_object('lotId', lot.lot_id, 'equipmentId', lot.machine_id, 'lotStart', replace(to_char((lot.lot_start AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'::text), '.000Z'::text, 'Z'::text), 'processJobType', 'MEASURE'), 'waferId', wafer.wafer_id, 'waferProcessingOrder', wafer.wafer_sequencenr))::text AS wafer_process_job_id,
    lot.id AS lot_metrology_step_id
   FROM (lisa.wafer_metrology_step wafer
     LEFT JOIN lisa.lot_metrology_step lot ON ((wafer.lot_metrology_step_id = lot.id)));


