--
-- Name: wafer_metrology_cd_kpis; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.wafer_metrology_cd_kpis (
    id numeric(18,0) NOT NULL,
    goodness_of_fit_mean numeric(38,19),
    goodness_of_fit_sigma numeric(38,19),
    goodness_of_fit_min numeric(38,19),
    goodness_of_fit_max numeric(38,19),
    residual_mean numeric(38,19),
    residual_max numeric(38,19),
    first_iteration_resid_mean numeric(38,19),
    first_iteration_resid_max numeric(38,19),
    nr_of_iterations_mean numeric(38,19),
    nr_of_iterations_max numeric(38,19),
    valid_count numeric(38,19),
    invalid_count numeric(38,19),
    location_group character varying(10)
);


