--
-- Name: wafer_metrology_residual_kpis; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.wafer_metrology_residual_kpis (
    id numeric(18,0) NOT NULL,
    centerspot_count_x numeric(38,19),
    centerspot_count_y numeric(38,19),
    centerspot_mean_x numeric(38,19),
    centerspot_mean_y numeric(38,19),
    centerspot_min_x numeric(38,19),
    centerspot_min_y numeric(38,19),
    centerspot_max_x numeric(38,19),
    centerspot_max_y numeric(38,19),
    centerspot_sigma_x numeric(38,19),
    centerspot_sigma_y numeric(38,19),
    centerspot_m3s_x numeric(38,19),
    centerspot_m3s_y numeric(38,19),
    crowning_top_down_count_x numeric(38,19),
    crowning_top_down_count_y numeric(38,19),
    crowning_top_down_mean_x numeric(38,19),
    crowning_top_down_mean_y numeric(38,19),
    crowning_top_down_min_x numeric(38,19),
    crowning_top_down_min_y numeric(38,19),
    crowning_top_down_max_x numeric(38,19),
    crowning_top_down_max_y numeric(38,19),
    crowning_top_down_sigma_x numeric(38,19),
    crowning_top_down_sigma_y numeric(38,19),
    crowning_top_down_m3s_x numeric(38,19),
    crowning_top_down_m3s_y numeric(38,19),
    crowning_left_right_count_x numeric(38,19),
    crowning_left_right_count_y numeric(38,19),
    crowning_left_right_mean_x numeric(38,19),
    crowning_left_right_mean_y numeric(38,19),
    crowning_left_right_min_x numeric(38,19),
    crowning_left_right_min_y numeric(38,19),
    crowning_left_right_max_x numeric(38,19),
    crowning_left_right_max_y numeric(38,19),
    crowning_left_right_sigma_x numeric(38,19),
    crowning_left_right_sigma_y numeric(38,19),
    crowning_left_right_m3s_x numeric(38,19),
    crowning_left_right_m3s_y numeric(38,19),
    residuals_m3s_x numeric(38,19),
    residuals_m3s_y numeric(38,19),
    job_id numeric(18,0)
);


