CREATE TABLE lisa.wafer_overlay_modeling_kpis (
    id numeric(18,0) NOT NULL,
    job_id numeric(18,0) NOT NULL,
    kpi_class character varying(4000),
    meas_valid_percentage numeric(38,19),
    meas_valid_percentage_limit numeric(38,19),
    meas_valid_x_percentage numeric(38,19),
    meas_valid_x_percentage_limit numeric(38,19),
    meas_valid_y_percentage numeric(38,19),
    meas_valid_y_percentage_limit numeric(38,19),
    filt_valid_percentage numeric(38,19),
    filt_valid_percentage_limit numeric(38,19),
    filt_valid_x_percentage numeric(38,19),
    filt_valid_x_percentage_limit numeric(38,19),
    filt_valid_y_percentage numeric(38,19),
    filt_valid_y_percentage_limit numeric(38,19),
    step_id character varying(255),
    model_name character varying(80),
    on_residuals_of character varying(255),
    value_of_n numeric(38,19),
    meas_max_n_percent numeric(38,19),
    meas_x_max_n_percent numeric(38,19),
    meas_y_max_n_percent numeric(38,19),
    filt_max_n_percent numeric(38,19),
    filt_x_max_n_percent numeric(38,19),
    filt_y_max_n_percent numeric(38,19),
    resi_max_n_percent numeric(38,19),
    resi_x_max_n_percent numeric(38,19),
    resi_y_max_n_percent numeric(38,19)
);


