--
-- Name: wafer_overlay_modeling_step; Type: TABLE; Schema: lisa; Owner: -; Tablespace: lisa_data
--

CREATE TABLE lisa.wafer_overlay_modeling_step (
    id numeric(18,0) NOT NULL,
    job_id numeric(18,0) NOT NULL,
    step_id character varying(255),
    modeling_state character varying(255),
    statistics_class character varying(4000),
    measured_x_total_count numeric(18,0),
    measured_x_inv_by_met_count numeric(18,0),
    measured_x_min numeric(38,19),
    measured_x_max numeric(38,19),
    measured_x_mean numeric(38,19),
    measured_x_sigma numeric(38,19),
    measured_x_m3s numeric(38,19),
    measured_y_total_count numeric(18,0),
    measured_y_inv_by_met_count numeric(18,0),
    measured_y_min numeric(38,19),
    measured_y_max numeric(38,19),
    measured_y_mean numeric(38,19),
    measured_y_sigma numeric(38,19),
    measured_y_m3s numeric(38,19),
    filtered_x_inv_by_hf_count numeric(18,0),
    filtered_x_min numeric(38,19),
    filtered_x_max numeric(38,19),
    filtered_x_mean numeric(38,19),
    filtered_x_sigma numeric(38,19),
    filtered_x_m3s numeric(38,19),
    filtered_y_inv_by_hf_count numeric(18,0),
    filtered_y_min numeric(38,19),
    filtered_y_max numeric(38,19),
    filtered_y_mean numeric(38,19),
    filtered_y_sigma numeric(38,19),
    filtered_y_m3s numeric(38,19),
    residual_x_inv_by_od_count numeric(18,0),
    residual_x_min numeric(38,19),
    residual_x_max numeric(38,19),
    residual_x_mean numeric(38,19),
    residual_x_sigma numeric(38,19),
    residual_x_m3s numeric(38,19),
    residual_y_inv_by_od_count numeric(18,0),
    residual_y_min numeric(38,19),
    residual_y_max numeric(38,19),
    residual_y_mean numeric(38,19),
    residual_y_sigma numeric(38,19),
    residual_y_m3s numeric(38,19),
    model_x_min numeric(38,19),
    model_x_max numeric(38,19),
    model_x_mean numeric(38,19),
    model_x_sigma numeric(38,19),
    model_x_m3s numeric(38,19),
    model_y_min numeric(38,19),
    model_y_max numeric(38,19),
    model_y_mean numeric(38,19),
    model_y_sigma numeric(38,19),
    model_y_m3s numeric(38,19),
    fingerprint_id character varying(255),
    model_name character varying(80),
    on_residuals_of character varying(255)
);


