    id numeric(18,0) NOT NULL,
    ma_cd_number_targets_wafer numeric(38,19),
    ma_cd_average_wafer numeric(38,19),
    ma_ov_number_targets_wafer numeric(38,19),
    ma_ov_average_wafer numeric(38,19),
    ma_focus_number_targets_wafer numeric(38,19),
    ma_focus_average_wafer numeric(38,19),
    timing_load_start timestamp with time zone,
    timing_load_end timestamp with time zone,
    timing_meas_start timestamp with time zone,
    timing_meas_end timestamp with time zone,
    timing_unload_start timestamp with time zone,
    timing_unload_end timestamp with time zone,
    timing_mach_entry_exit_start timestamp with time zone,
    timing_mach_entry_exit_end timestamp with time zone
